from openpyxl import load_workbook
from openpyxl.styles import Font
from openpyxl.utils import get_column_letter

path = "sales_data.xlsx"
wb = load_workbook(path, data_only=False)

def norm(v):
    return str(v).strip().lower() if v is not None else ""

# pick the sheet whose headers best match sales/profit vocabulary
best_ws, best_score = None, -1
for ws in wb.worksheets:
    score = 0
    for row in ws.iter_rows(min_row=1, max_row=min(10, ws.max_row)):
        for c in row:
            h = norm(c.value)
            if any(k in h for k in ("profit", "revenue", "sales", "cost", "margin")):
                score += 1
    if score > best_score:
        best_ws, best_score = ws, score
if best_ws is None:
    raise SystemExit("No worksheets found")
ws = best_ws
print("Using sheet:", ws.title)

# locate header row (row with the most keyword-matching labels)
hdr_row, best = None, 0
for r in range(1, min(10, ws.max_row) + 1):
    s = sum(1 for c in ws[r] if any(k in norm(c.value) for k in ("profit", "revenue", "sales", "cost", "margin")))
    if s > best:
        best, hdr_row = s, r
if hdr_row is None or best == 0:
    raise SystemExit("Could not locate a header row containing profit/revenue/cost labels")

headers = {c.column: norm(c.value) for c in ws[hdr_row] if c.value is not None}

def find(*pats):
    for col, h in headers.items():
        if any(p in h for p in pats):
            return col
    return None

profit_col = find("profit")
revenue_col = find("revenue") or find("sales", "total")
cost_col = find("cost")

if profit_col and revenue_col:
    num_col, den_col = profit_col, revenue_col
    kind = "profit / revenue"
elif revenue_col and cost_col:
    num_col, den_col = None, None
    kind = "(revenue - cost) / revenue"
else:
    raise SystemExit("Could not find required columns. Headers: " + repr(headers))

L = get_column_letter
new_col = max([ws.max_column] + list(headers.keys())) + 1
new_letter = L(new_col)
hdr_cell = ws.cell(row=hdr_row, column=new_col, value="Profit Margin %")
hdr_cell.font = Font(bold=True)

count = 0
for r in range(hdr_row + 1, ws.max_row + 1):
    if all(ws.cell(row=r, column=c).value in (None, "") for c in headers):
        continue
    if num_col is not None:
        f = f"=IFERROR({L(num_col)}{r}/{L(den_col)}{r},\"\")"
    else:
        f = f"=IFERROR(({L(revenue_col)}{r}-{L(cost_col)}{r})/{L(revenue_col)}{r},\"\")"
    cell = ws.cell(row=r, column=new_col, value=f)
    cell.number_format = '0.0%;-0.0%;"-"'
    count += 1

wb.save(path)
print("Saved", path)
print("Added column", new_letter, "with", count, "formulas (", kind, ")")
print("Header row:", hdr_row, "| Headers:", {L(k): v for k, v in headers.items()})

import zipfile, re, os, sys
import xml.etree.ElementTree as ET

PATH = "sales_data.xlsx"
MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
NS = "{%s}" % MAIN
REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"

def q(tag):
    return NS + tag

def col_num(ref):
    m = re.match(r"([A-Z]+)", ref or "")
    if not m:
        return None
    n = 0
    for ch in m.group(1):
        n = n * 26 + (ord(ch) - 64)
    return n

def col_letter(n):
    s = ""
    while n > 0:
        n, r = divmod(n - 1, 26)
        s = chr(65 + r) + s
    return s

def register_ns(text):
    for m in re.finditer(r'xmlns:([A-Za-z0-9_]+)="([^"]+)"', text):
        ET.register_namespace(m.group(1), m.group(2))
    m = re.search(r'xmlns="([^"]+)"', text)
    if m:
        ET.register_namespace("", m.group(1))

zin = zipfile.ZipFile(PATH)
names = set(zin.namelist())

wb_xml = zin.read("xl/workbook.xml").decode("utf-8", "replace")
register_ns(wb_xml)
wb_root = ET.fromstring(wb_xml)
rels_xml = zin.read("xl/_rels/workbook.xml.rels").decode("utf-8", "replace")
rels_root = ET.fromstring(rels_xml)
rel_map = {r.get("Id"): r.get("Target") for r in rels_root.findall(q("Relationship"))}

sheet_paths = []
for s in wb_root.findall(q("sheets") + "/" + q("sheet")):
    rid = s.get("{%s}id" % REL)
    tgt = rel_map.get(rid, "")
    if tgt.startswith("/"):
        tgt = tgt[1:]
    elif not tgt.startswith("xl/"):
        tgt = "xl/" + tgt
    sheet_paths.append((s.get("name"), tgt))

shared = []
if "xl/sharedStrings.xml" in names:
    ss = ET.fromstring(zin.read("xl/sharedStrings.xml"))
    for si in ss.findall(q("si")):
        shared.append("".join(t.text or "" for t in si.iter(q("t"))))

def cell_text(c):
    t = c.get("t")
    if t == "inlineStr":
        return "".join(x.text or "" for x in c.iter(q("t")))
    v = c.find(q("v"))
    raw = v.text if v is not None else ""
    if t == "s":
        try:
            return shared[int(raw)]
        except Exception:
            return ""
    return raw

KEYWORDS = ("profit", "revenue", "sales", "cost", "margin")

def analyze_sheet(path):
    raw = zin.read(path).decode("utf-8", "replace")
    register_ns(raw)
    root = ET.fromstring(raw)
    sd = root.find(q("sheetData"))
    rows = []
    for row in sd.findall(q("row")):
        try:
            rn = int(row.get("r"))
        except Exception:
            rn = len(rows) + 1
        cells = []
        for c in row.findall(q("c")):
            cn = col_num(c.get("r"))
            if cn is None:
                continue
            cells.append((cn, cell_text(c).strip().lower(), c))
        rows.append((rn, cells))
    return root, sd, rows

best = None
best_path = None
for name, path in sheet_paths:
    if path not in names:
        continue
    root, sd, rows = analyze_sheet(path)
    score = 0
    for rn, cells in rows[:10]:
        for cn, txt, c in cells:
            if any(k in txt for k in KEYWORDS):
                score += 1
    print("sheet:", name, "score:", score)
    if best is None or score > best[0]:
        best = (score, name, path, root, sd, rows)
        best_path = path

if best is None or best[0] == 0:
    print("COULD NOT LOCATE header row with profit/revenue/cost labels")
    sys.exit(2)

score, sheet_name, sheet_path, root, sd, rows = best

hdr_rn, hdr_score = None, 0
for rn, cells in rows[:10]:
    s = sum(1 for cn, txt, c in cells if any(k in txt for k in KEYWORDS))
    if s > hdr_score:
        hdr_score, hdr_rn = s, rn

if hdr_rn is None:
    print("No header row found")
    sys.exit(2)

headers = {}
for rn, cells in rows:
    if rn == hdr_rn:
        headers = {cn: txt for cn, txt, c in cells if txt}
        break

def find(*pats):
    for cn, txt in headers.items():
        if any(p in txt for p in pats):
            return cn
    return None

profit_col = find("profit")
revenue_col = find("revenue") or find("sales", "total")
cost_col = find("cost")

if profit_col and revenue_col:
    num_col, den_col = profit_col, revenue_col
    kind = "profit / revenue"
elif revenue_col and cost_col:
    num_col, den_col = None, None
    kind = "(revenue - cost) / revenue"
else:
    print("Could not find required columns. Headers:", headers)
    sys.exit(2)

max_col = max((cn for rn, cells in rows for cn, txt, c in cells), default=1)
new_col = max(max_col, max(headers)) + 1
L = col_letter(new_col)

# styles: add percentage number format
style_idx = None
if "xl/styles.xml" in names:
    st_raw = zin.read("xl/styles.xml").decode("utf-8", "replace")
    register_ns(st_raw)
    st_root = ET.fromstring(st_raw)
    numFmts = st_root.find(q("numFmts"))
    if numFmts is None:
        numFmts = ET.Element(q("numFmts"))
        st_root.insert(0, numFmts)
    nid = 164
    for nf in numFmts.findall(q("numFmt")):
        try:
            nid = max(nid, int(nf.get("numFmtId", 0)) + 1)
        except Exception:
            pass
    nf = ET.SubElement(numFmts, q("numFmt"))
    nf.set("numFmtId", str(nid))
    nf.set("formatCode", "0.0%")
    cellXfs = st_root.find(q("cellXfs"))
    if cellXfs is not None:
        xf = ET.SubElement(cellXfs, q("xf"))
        xf.set("numFmtId", str(nid))
        xf.set("applyNumberFormat", "1")
        style_idx = len(cellXfs.findall(q("xf"))) - 1
    replacements = {"xl/styles.xml": ET.tostring(st_root, encoding="utf-8", xml_declaration=True)}
else:
    replacements = {}

count = 0
last_rn = hdr_rn
for rn, cells in rows:
    last_rn = max(last_rn, rn)
    if rn == hdr_rn:
        c = ET.SubElement(sd, q("c"))
        c.set("r", "%s%d" % (L, rn))
        c.set("t", "inlineStr")
        is_el = ET.SubElement(c, q("is"))
        t_el = ET.SubElement(is_el, q("t"))
        t_el.text = "Profit Margin %"
        continue
    if not cells:
        continue
    if num_col is not None:
        f = 'IFERROR(%s%d/%s%d,"")' % (col_letter(num_col), rn, col_letter(den_col), rn)
    else:
        f = 'IFERROR((%s%d-%s%d)/%s%d,"")' % (col_letter(revenue_col), rn, col_letter(cost_col), rn, col_letter(revenue_col), rn)
    c = ET.SubElement(sd, q("c"))
    c.set("r", "%s%d" % (L, rn))
    if style_idx is not None:
        c.set("s", str(style_idx))
    f_el = ET.SubElement(c, q("f"))
    f_el.text = f
    count += 1

dim = root.find(q("dimension"))
if dim is not None:
    dim.set("ref", "A1:%s%d" % (L, last_rn))

replacements[sheet_path] = ET.tostring(root, encoding="utf-8", xml_declaration=True)

tmp = PATH + ".tmp"
with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
    for item in zin.infolist():
        data = replacements.get(item.filename)
        if data is None:
            data = zin.read(item.filename)
        zout.writestr(item, data)
zin.close()
os.replace(tmp, PATH)

print("OK sheet=%s header_row=%d new_column=%s rows=%d formula=%s" % (sheet_name, hdr_rn, L, count, kind))
print("Headers:", {col_letter(k): v for k, v in headers.items()})

