print(sys.executable)
for m in ["openpyxl", "pandas", "xlrd", "xlsxwriter"]:
    try:
        mod = importlib.import_module(m)
        print(m, "OK", getattr(mod, "__version__", "?"))
    except Exception as e:
        print(m, "MISSING", type(e).__name__)

